The three points $(3,-5)$, $(-a + 2, 3)$, and $(2a+3,2)$ lie on the same line.  What is $a$?

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double x1 = 3, y1 = -5;
    double x2 = -a + 2, y2 = 3;
    double x3 = 2*a + 3, y3 = 2;

    double slope1 = (y2 - y1) / (x2 - x1);
    double slope2 = (y3 - y2) / (x3 - x2);

    if (slope1 == slope2) {
        double x = (y1 - y3) / (slope1 - slope2);
        double y = slope1 * x + y1;
        double a = (x - 2) / 2;
        cout << "a = " << a << endl;
    } else {
        cout << "The points do not lie on the same line." << endl;
    }

    return 0;
}

